  2011  static avifBool avifParseFileTypeBox(avifFileType * ftyp, const uint8_t * raw, size_t rawLen)
  2012  {
  2013      BEGIN_STREAM(s, raw, rawLen);
  2014
  2015      CHECK(avifROStreamRead(&s, ftyp->majorBrand, 4));
  2016      CHECK(avifROStreamReadU32(&s, &ftyp->minorVersion));
  2017
  2018      size_t compatibleBrandsBytes = avifROStreamRemainingBytes(&s);
  2019      if ((compatibleBrandsBytes % 4) != 0) {
  2020          return AVIF_FALSE;
  2021      }
  2022      ftyp->compatibleBrands = avifROStreamCurrent(&s);
  2023      CHECK(avifROStreamSkip(&s, compatibleBrandsBytes));
  2024      ftyp->compatibleBrandsCount = (int)compatibleBrandsBytes / 4;
  2025
  2026      return AVIF_TRUE;
  2027  }
