  2029  static avifResult avifParse(avifDecoder * decoder)
  2030  {
  2031      avifResult readResult;
  2032      size_t parseOffset = 0;
  2033      avifDecoderData * data = decoder->data;
  2034
  2035      for (;;) {
  2036          // Read just enough to get the next box header (a max of 32 bytes)
  2037          avifROData headerContents;
  2038          readResult = decoder->io->read(decoder->io, 0, parseOffset, 32, &headerContents);
  2039          if (readResult != AVIF_RESULT_OK) {
  2040              return readResult;
  2041          }
  2042          if (!headerContents.size) {
  2043              // If we got AVIF_RESULT_OK from the reader but received 0 bytes,
  2044              // This we've reached the end of the file with no errors. Hooray!
  2045              break;
  2046          }
  2047
  2048          // Parse the header, and find out how many bytes it actually was
  2049          BEGIN_STREAM(headerStream, headerContents.data, headerContents.size);
  2050          avifBoxHeader header;
  2051          CHECK(avifROStreamReadBoxHeader(&headerStream, &header));
  2052          parseOffset += headerStream.offset;
  2053
  2054          // Try to get the remainder of the box, if necessary
  2055          avifROData boxContents = AVIF_DATA_EMPTY;
  2056
  2057          // TODO: reorg this code to only do these memcmps once each
  2058          if (!memcmp(header.type, "ftyp", 4) || (!memcmp(header.type, "meta", 4) || !memcmp(header.type, "moov", 4))) {
  2059              readResult = decoder->io->read(decoder->io, 0, parseOffset, header.size, &boxContents);
  2060              if (readResult != AVIF_RESULT_OK) {
  2061                  return readResult;
  2062              }
  2063              if (boxContents.size != header.size) {
  2064                  // A truncated box, bail out
  2065                  return AVIF_RESULT_BMFF_PARSE_FAILED;
  2066              }
  2067          }
  2068
  2069          if (!memcmp(header.type, "ftyp", 4)) {
  2070              avifRWDataSet(&data->ftypData, boxContents.data, boxContents.size);
  2071              CHECK(avifParseFileTypeBox(&data->ftyp, data->ftypData.data, data->ftypData.size));
  2072          } else if (!memcmp(header.type, "meta", 4)) {
  2073              CHECK(avifParseMetaBox(data->meta, boxContents.data, boxContents.size));
  2074          } else if (!memcmp(header.type, "moov", 4)) {
  2075              CHECK(avifParseMoovBox(data, boxContents.data, boxContents.size));
  2076          }
  2077
  2078          parseOffset += header.size;
  2079      }
  2080      return AVIF_RESULT_OK;
  2081  }
